def _format_insn(itype, fields):
    """Format an instruction. Returns (mnemonic, operands) strings."""
    if itype == ITYPE_NOP:
        return "NOP", ""
    elif itype == ITYPE_DAR:
        return "DAR", f"$ar{fields["d"]}"
    elif itype == ITYPE_IAR:
        return "IAR", f"$ar{fields["d"]}"
    elif itype == ITYPE_SUBARN:
        return "SUBARN", f"$ar{fields["d"]}"
    elif itype == ITYPE_ADDARN:
        return "ADDARN", f"$ar{fields["d"]}, $ix{fields["s"]}"
    elif itype == ITYPE_HALT:
        return "HALT", ""
    elif itype == ITYPE_LOOP_REG:
        return "LOOP", f"${reg5_name(fields["reg"])}"
    elif itype == ITYPE_BLOOP:
        return "BLOOP", f"${reg5_name(fields["reg"])}, {fields["addr"]:#06x}"
    elif itype == ITYPE_LRI:
        return "LRI", f"${reg5_name(fields["rd"])}, #{fields["imm"]:#06x}"
    elif itype == ITYPE_LR:
        return "LR", f"${reg5_name(fields["rd"])}, @{fields["addr"]:#06x}"
    elif itype == ITYPE_SR:
        return "SR", f"@{fields["addr"]:#06x}, ${reg5_name(fields["rs"])}"
    elif itype == ITYPE_IFCC:
        if fields["cond"] == 15:
            return "IF", ""
        else:
            return f"IF{cc_name(fields["cond"])}", ""
    elif itype == ITYPE_JCC:
        if fields["cond"] == 15:
            return "JMP", f"{fields["addr"]:#06x}"
        else:
            return f"J{cc_name(fields["cond"])}", f"{fields["addr"]:#06x}"
    elif itype == ITYPE_CALLCC:
        if fields["cond"] == 15:
            return "CALL", f"{fields["addr"]:#06x}"
        else:
            return f"CALL{cc_name(fields["cond"])}", f"{fields["addr"]:#06x}"
    elif itype == ITYPE_RETCC:
        if fields["cond"] == 15:
            return "RET", ""
        else:
            return f"RET{cc_name(fields["cond"])}", ""
    elif itype == ITYPE_RTICC:
        if fields["cond"] == 15:
            return "RTI", ""
        else:
            return f"RTI{cc_name(fields["cond"])}", ""
    elif itype == ITYPE_ADDI:
        return "ADDI", f"$ac{fields["d"]}.m, #{fields["imm"]:#06x}"
    elif itype == ITYPE_XORI:
        return "XORI", f"$ac{fields["d"]}.m, #{fields["imm"]:#06x}"
    elif itype == ITYPE_ANDI:
        return "ANDI", f"$ac{fields["d"]}.m, #{fields["imm"]:#06x}"
    elif itype == ITYPE_ORI:
        return "ORI", f"$ac{fields["d"]}.m, #{fields["imm"]:#06x}"
    elif itype == ITYPE_CMPI:
        return "CMPI", f"$ac{fields["d"]}, #{fields["imm"]:#06x}"
    elif itype == ITYPE_ANDF:
        return "ANDF", f"$ac{fields["d"]}.m, #{fields["imm"]:#06x}"
    elif itype == ITYPE_ANDCF:
        return "ANDCF", f"$ac{fields["d"]}.m, #{fields["imm"]:#06x}"
    elif itype == ITYPE_ILRR:
        return "ILRR", f"$ac{fields["d"]}.m, @$ar{fields["s"]}"
    elif itype == ITYPE_ILRRD:
        return "ILRRD", f"$ac{fields["d"]}.m, @$ar{fields["s"]}"
    elif itype == ITYPE_ILRRI:
        return "ILRRI", f"$ac{fields["d"]}.m, @$ar{fields["s"]}"
    elif itype == ITYPE_ILRRN:
        return "ILRRN", f"$ac{fields["d"]}.m, @$ar{fields["s"]}"
    elif itype == ITYPE_LSRN:
        return "LSRN", ""
    elif itype == ITYPE_ASRN:
        return "ASRN", ""
    elif itype == ITYPE_ADDIS:
        return "ADDIS", f"$ac{fields["d"]}, #{fields["imm"]}"
    elif itype == ITYPE_CMPIS:
        return "CMPIS", f"$ac{fields["d"]}, #{fields["imm"]}"
    elif itype == ITYPE_LRIS:
        return "LRIS", f"${acreg3_name(fields["reg"])}, #{fields["imm"]}"
    elif itype == ITYPE_LOOPI:
        return "LOOPI", f"#{fields["imm"]}"
    elif itype == ITYPE_BLOOPI:
        return "BLOOPI", f"#{fields["imm"]}, {fields["addr"]:#06x}"
    elif itype == ITYPE_SBCLR:
        return "SBCLR", f"#{fields["bit"]}"
    elif itype == ITYPE_SBSET:
        return "SBSET", f"#{fields["bit"]}"
    elif itype == ITYPE_LSL:
        return "LSL", f"$ac{fields["r"]}, #{fields["n"]}"
    elif itype == ITYPE_LSR:
        return "LSR", f"$ac{fields["r"]}, #{fields["n"]}"
    elif itype == ITYPE_ASL:
        return "ASL", f"$ac{fields["r"]}, #{fields["n"]}"
    elif itype == ITYPE_ASR:
        return "ASR", f"$ac{fields["r"]}, #{fields["n"]}"
    elif itype == ITYPE_SI:
        return "SI", f"@{(65280 + fields["mem"]):#06x}, #{fields["imm"]:#06x}"
    elif itype == ITYPE_JRCC:
        if fields["cond"] == 15:
            return "JMPR", f"${reg3_name(fields["reg"])}"
        else:
            return f"JR{cc_name(fields["cond"])}", f"${reg3_name(fields["reg"])}"
    elif itype == ITYPE_CALLRCC:
        if fields["cond"] == 15:
            return "CALLR", f"${reg3_name(fields["reg"])}"
        else:
            return f"CALLR{cc_name(fields["cond"])}", f"${reg3_name(fields["reg"])}"
    elif itype == ITYPE_LRR:
        return "LRR", f"${reg5_name(fields["d"])}, @$ar{fields["s"]}"
    elif itype == ITYPE_LRRD:
        return "LRRD", f"${reg5_name(fields["d"])}, @$ar{fields["s"]}"
    elif itype == ITYPE_LRRI:
        return "LRRI", f"${reg5_name(fields["d"])}, @$ar{fields["s"]}"
    elif itype == ITYPE_LRRN:
        return "LRRN", f"${reg5_name(fields["d"])}, @$ar{fields["s"]}"
    elif itype == ITYPE_SRR:
        return "SRR", f"@$ar{fields["d"]}, ${reg5_name(fields["s"])}"
    elif itype == ITYPE_SRRD:
        return "SRRD", f"@$ar{fields["d"]}, ${reg5_name(fields["s"])}"
    elif itype == ITYPE_SRRI:
        return "SRRI", f"@$ar{fields["d"]}, ${reg5_name(fields["s"])}"
    elif itype == ITYPE_SRRN:
        return "SRRN", f"@$ar{fields["d"]}, ${reg5_name(fields["s"])}"
    elif itype == ITYPE_MRR:
        return "MRR", f"${reg5_name(fields["dst"])}, ${reg5_name(fields["src"])}"
