    def __init__(self):
        ida_idp.processor_t.__init__(self)

    def ev_ana_insn(self, insn):
        data = ida_bytes.get_bytes(insn.ea, 4)
        if data is None:
            return 0
        result = _decode(data)
        if result is None:
            return 0
        itype, fields, size = result
        insn.itype = itype
        insn.size = size
        # Populate operands from decoded fields
        op_idx = 0
        for name, value in fields.items():
            if op_idx >= 6:
                break
            # Skip sub-decoder dicts (extension opcodes) - not operands
            if isinstance(value, dict):
                continue
            # Ensure value is unsigned for IDA's ea_t fields
            if isinstance(value, int) and value < 0:
                value = value & 0xFFFFFFFF
            op = insn.ops[op_idx]
            if name in ["reg", "rs", "rd"]:
                op.type = ida_ua.o_reg
                op.reg = value
            elif name in ["addr"]:
                op.type = ida_ua.o_near
                op.addr = value * 2
            elif name in ["mem"]:
                op.type = ida_ua.o_mem
                op.addr = value * 2
            else:
                op.type = ida_ua.o_imm
                op.value = value
            op_idx += 1
        return insn.size

    def ev_out_insn(self, outctx):
        insn = outctx.insn
        # Re-decode to get full fields (including sub-decoder dicts)
        data = ida_bytes.get_bytes(insn.ea, 4)
        if data is None:
            return False
        result = _decode(data)
        if result is None:
            return False
        _, fields, _ = result
        _ADDR_FIELDS = {"addr"}
        fields = {k: (v * 2 if k in _ADDR_FIELDS else v) for k, v in fields.items()}
        mnemonic, operands = _format_insn(insn.itype, fields)
        outctx.out_custom_mnem(mnemonic)
        if operands:
            outctx.out_line(" " + operands)
        outctx.flush_outbuf()
        return True

    def ev_out_operand(self, outctx, op):
        return True

    def ev_emu_insn(self, insn):
        feature = insn.get_canon_feature()
        if feature & ida_idp.CF_JUMP:
            ida_problems.remember_problem(ida_problems.PR_JUMP, insn.ea)
        if feature & ida_idp.CF_STOP == 0:
            ida_xref.add_cref(insn.ea, insn.ea + insn.size, ida_xref.fl_F)
        # Add xrefs for address operands
        for i in range(6):
            op = insn.ops[i]
            if op.type == ida_ua.o_void:
                break
            if op.type == ida_ua.o_near:
                if feature & ida_idp.CF_CALL:
                    insn.add_cref(op.addr, op.offb, ida_xref.fl_CN)
                else:
                    insn.add_cref(op.addr, op.offb, ida_xref.fl_JN)
            elif op.type == ida_ua.o_mem:
                insn.add_dref(op.addr, op.offb, ida_xref.dr_R)
        return True


